import "core-js/modules/web.url-search-params.delete.js";
import "core-js/modules/web.url-search-params.has.js";
import "core-js/modules/web.url-search-params.size.js";
import api from '../../services/api';
export default {
  name: 'AdminSalesReports',
  data() {
    return {
      from: '',
      to: '',
      rows: [],
      submissions: [],
      storeFilter: '',
      periodFilter: ''
    };
  },
  created() {
    this.fetch();
    this.fetchSubmissions();
  },
  methods: {
    async fetch() {
      const {
        data
      } = await api.get('/admin/reports/sales', {
        params: {
          from: this.from || undefined,
          to: this.to || undefined
        }
      });
      this.rows = data;
    },
    async fetchSubmissions() {
      const params = {};
      if (this.storeFilter) params.storeOwnerId = this.storeFilter;
      if (this.periodFilter) params.period = this.periodFilter;
      const {
        data
      } = await api.get('/admin/reports/submissions', {
        params
      });
      this.submissions = data;
    },
    async downloadFile(r) {
      try {
        const res = await api.get(`/admin/reports/submissions/${r.id}/file`, {
          responseType: 'blob'
        });
        let filename = r.report_file_name || `submission_${r.id}.pdf`;
        const disposition = res.headers?.['content-disposition'] || '';
        const m = disposition.match(/filename="?([^";]+)"?/i);
        if (m && m[1]) filename = m[1];
        const mimeType = res.headers?.['content-type'] || 'application/octet-stream';
        const blob = new Blob([res.data], {
          type: mimeType
        });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        a.click();
        URL.revokeObjectURL(url);
      } catch (err) {
        alert(err.response?.data?.message || 'Failed to download file');
      }
    }
  }
};
